/// One saved pull with everything the History table needs, newest first from the backend.
class HistoryPull {
  final String id;
  final String gachaType;
  final String gachaId;
  final String itemId;
  final String name;
  final String itemType;

  /// `YYYY-MM-DD HH:MM:SS`, the account's server-local time.
  final String time;

  /// 3 / 4 / 5 for every game (Zenless B / A / S are mapped).
  final int rank;

  /// Short pool name for the table, e.g. "Character".
  final String pool;

  /// Key of the History banner filter this pull belongs to (see `GameMeta`); empty if none.
  final String bannerKey;

  /// "Event name · Featured A / Featured B"; `None` when the banner list cannot place the pull.
  final String? bannerName;

  /// Pulls since the last 5★ (5★ rows) or last 4★/5★ (4★ rows) when this pull was made.
  final int? pity;

  const HistoryPull({
    required this.id,
    required this.gachaType,
    required this.gachaId,
    required this.itemId,
    required this.name,
    required this.itemType,
    required this.time,
    required this.rank,
    required this.pool,
    required this.bannerKey,
    this.bannerName,
    this.pity,
  });

  @override
  int get hashCode =>
      id.hashCode ^
      gachaType.hashCode ^
      gachaId.hashCode ^
      itemId.hashCode ^
      name.hashCode ^
      itemType.hashCode ^
      time.hashCode ^
      rank.hashCode ^
      pool.hashCode ^
      bannerKey.hashCode ^
      bannerName.hashCode ^
      pity.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is HistoryPull &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          gachaType == other.gachaType &&
          gachaId == other.gachaId &&
          itemId == other.itemId &&
          name == other.name &&
          itemType == other.itemType &&
          time == other.time &&
          rank == other.rank &&
          pool == other.pool &&
          bannerKey == other.bannerKey &&
          bannerName == other.bannerName &&
          pity == other.pity;
}

